async function loadSavedCards(){savedCards=[];const client=siteClient();if(!client?.auth?.getUser)return;try{const {data:{user}={},error:userError}=await client.auth.getUser();if(userError||!user){if(reviewUser!=='guest'){reviewUser='guest';loadReview();}return;}const id=String(user.id);if(reviewUser!==id){reviewUser=id;loadReview();}const {data,error}=await client.from('cards').select('word,translation').eq('user_id',id).limit(500);if(error)throw error;savedCards=Array.isArray(data)?data:[];}catch(_){cardNotice=cr('syncUnavailable');}}
